// Fusion des recherches, dédoublonnage par chunk_id (score maximal conservé), puis sélection :
// les meilleurs chunks de la requête « contre » sont garantis, plafond par document, nombre maximal de chunks.
// Paramètres : prompts/sections.json (parametres_retrieval). Pas de MMR : règle déterministe.
const p = $('Préparer les sections').first().json.parametres;
const requetes = $('Requêtes de la section').all();
const parChunk = new Map();
$input.all().forEach(({ json }, i) => {
  const q = $('Requêtes de la section').itemMatching(i).json;
  const m = json.document.metadata;
  const c = parChunk.get(m.chunk_id) ?? {
    chunk_id: m.chunk_id, doc_id: m.doc_id, page: m.page, role: m.role,
    texte: json.document.pageContent, score: 0, score_contre: null, requetes: [],
  };
  c.score = Math.max(c.score, json.score);
  if (q.contre) c.score_contre = Math.max(c.score_contre ?? 0, json.score);
  c.requetes.push(q.requete);
  parChunk.set(m.chunk_id, c);
});
const candidats = [...parChunk.values()];
const retenus = [];
const parDoc = {};
const prendre = (c) => {
  if (retenus.includes(c) || retenus.length >= p.chunks_retenus_max || (parDoc[c.doc_id] ?? 0) >= p.plafond_par_document) return false;
  retenus.push(c);
  parDoc[c.doc_id] = (parDoc[c.doc_id] ?? 0) + 1;
  return true;
};
let garantis = 0;
for (const c of candidats.filter((c) => c.score_contre !== null).sort((a, b) => b.score_contre - a.score_contre)) {
  if (garantis >= p.requete_contre.chunks_garantis) break;
  if (prendre(c)) garantis++;
}
candidats.sort((a, b) => b.score - a.score).forEach(prendre);
return [{ json: {
  section: requetes[0].json.section,
  chunks: retenus,
  stats: { requetes: requetes.length, candidats: candidats.length, retenus: retenus.length, garantis_contre: garantis, par_document: parDoc },
} }];

// Remplit le prompt versionné (prompts/redacteur_v1.md) avec la section et ses extraits.
// Conclusion : la consigne est suivie des sections déjà rédigées (redacteur_v1.md n'a pas d'autre emplacement pour elles).
const prep = $('Préparer les sections').first().json;
const { section, chunks, stats, sections_redigees } = $json;
const documents = prep.meta
  .filter((d) => chunks.some((c) => c.doc_id === d.doc_id))
  .map((d) => `- ${d.doc_id} : ${d.reference}`)
  .join('\n');
const extraits = chunks
  .map((c) => `[${c.chunk_id}] ${c.doc_id} · rôle : ${c.role} · page ${c.page}\n${c.texte}`)
  .join('\n\n---\n\n');
const consigne = sections_redigees
  ? `${section.consigne}\n\nSections déjà rédigées, à synthétiser (chaque paragraphe est suivi des chunk_id qu'il cite) :\n\n${sections_redigees}`
  : section.consigne;
const valeurs = { SECTION_ID: section.id, TITRE: section.titre, CONSIGNE: consigne, POSITION: 'POUR', DOCUMENTS: documents, EXTRAITS: extraits };
const prompt = prep.template.replace(/\{\{(\w+)\}\}/g, (m, k) => valeurs[k] ?? m);
// Schéma imposé à Gemini (mode JSON). G1 vérifie quand même la structure reçue.
const chaine = { type: 'STRING' };
const schema = {
  type: 'OBJECT',
  properties: {
    section: chaine,
    paragraphes: { type: 'ARRAY', items: { type: 'OBJECT', properties: { texte: chaine, citations: { type: 'ARRAY', items: chaine } }, required: ['texte', 'citations'] } },
    contre_arguments_traites: { type: 'ARRAY', items: chaine },
  },
  required: ['section', 'paragraphes', 'contre_arguments_traites'],
};
return [{ json: { section, chunks, stats, modele: prep.modele, prompt, schema } }];

// G1 structure, G2 citations, G4 chiffres, G5 formulations absolues : détection et signalement seulement, sans nouvelle tentative (pipeline.md, WF10 C).
const MARQUEUR = '[INFORMATION NON DISPONIBLE DANS LE CORPUS]';
const { section, chunks, stats } = $('Prompt du rédacteur').first().json;
const recuperes = new Map(chunks.map((c) => [c.chunk_id, c]));
const r = $json;

// G1 : appel réussi, JSON valide, champs présents, au moins un paragraphe.
const g1 = [];
let sortie = null;
if (r.statusCode !== 200) {
  g1.push(`appel Gemini en échec (HTTP ${r.statusCode}) : ${r.body?.error?.message ?? ''}`);
} else {
  const texte = (r.body?.candidates?.[0]?.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text).join('');
  try { sortie = JSON.parse(texte); } catch { g1.push("la réponse n'est pas du JSON valide"); }
}
if (sortie && (!Array.isArray(sortie.paragraphes) || sortie.paragraphes.length === 0)) g1.push('aucun paragraphe');
if (sortie && !Array.isArray(sortie.contre_arguments_traites)) g1.push('champ contre_arguments_traites absent');

// G4 : nombres comparés après normalisation (virgule décimale française, séparateurs de milliers).
const nombres = (s) => [...new Set(s
  .replace(/\b[A-Z]\d{2}-[0-9a-f]{8}\b/g, '')
  .replace(/(\d)[\s  ](?=\d{3}\b)/g, '$1')
  .replace(/(\d),(\d)/g, '$1.$2')
  .match(/\d+(?:\.\d+)?/g) ?? [])];
const normSource = (s) => s.replace(/(\d),(?=\d{3}\b)/g, '$1');
const present = (n, textes) => textes.some((t) => new RegExp(`(?<![\\d.])${n.replace('.', '\\.')}(?!\\d|\\.\\d)`).test(normSource(t)));

// G5 : formulations absolues interdites, reprises de la règle 7 de redacteur_v1.md (« prouve » et ses formes, « toujours », « aucun risque »).
const ABSOLUES = /(?<!\p{L})(?:prouv\p{L}*|toujours|aucun\s+risque)(?!\p{L})/giu;
const absolues = (s) => [...new Set((s.match(ABSOLUES) ?? []).map((m) => m.toLowerCase().replace(/\s+/g, ' ')))];

const paragraphes = (sortie?.paragraphes ?? []).map((par) => {
  const alertes = [];
  const citations = par.citations ?? [];
  // G2 : chaque chunk_id cité doit faire partie des chunks récupérés ; un paragraphe factuel doit citer.
  const inconnues = citations.filter((id) => !recuperes.has(id));
  if (inconnues.length) alertes.push(`G2 : citation hors des chunks récupérés (${inconnues.join(', ')})`);
  if (!citations.length && !par.texte.includes(MARQUEUR)) alertes.push('G2 : paragraphe sans citation');
  const textesCites = citations.filter((id) => recuperes.has(id)).map((id) => recuperes.get(id).texte);
  const absents = nombres(par.texte).filter((n) => !present(n, textesCites));
  if (absents.length) alertes.push(`G4 : nombre(s) absent(s) des chunks cités (${absents.join(', ')})`);
  const formules = absolues(par.texte);
  if (formules.length) alertes.push(`G5 : formulation absolue (${formules.map((f) => `« ${f} »`).join(', ')})`);
  return { texte: par.texte, citations, alertes };
});
const contre = sortie?.contre_arguments_traites ?? [];
const alertes_section = contre.filter((id) => !recuperes.has(id)).map((id) => `G2 : contre-argument hors des chunks récupérés (${id})`);
return [{ json: {
  section, g1, alertes_section, paragraphes, contre_arguments_traites: contre, chunks, stats,
  usage: r.body?.usageMetadata, version: r.body?.modelVersion,
} }];

// Assemblage : chunk_id → [n, p. X] (n = numéro du document, dans l'ordre de première citation),
// bibliographie générée depuis corpus/meta.json (jamais par le LLM), paragraphes signalés marqués ⚠.
// Sorties : argumentaire_<run_id>.md, verif_<run_id>.json, une ligne ajoutée à runs.jsonl.
const prep = $('Préparer les sections').first().json;
// Sections : sortie « done » de la boucle ; conclusion : entrée de ce nœud, si elle a été générée.
const sections = [
  ...$('Une section à la fois').all(0).map(({ json }) => json),
  ...$input.all().map(({ json }) => json).filter((s) => s.section.id === 'conclusion'),
];
const numeros = new Map();
const renvoi = (citations, chunks) => {
  const etiquettes = [...new Set(citations.map((id) => {
    const c = chunks.find((x) => x.chunk_id === id);
    if (!c) return '?';
    if (!numeros.has(c.doc_id)) numeros.set(c.doc_id, numeros.size + 1);
    return `${numeros.get(c.doc_id)}, p. ${c.page}`;
  }))];
  return etiquettes.length ? ` [${etiquettes.join(' ; ')}]` : '';
};
const lignes = [
  "# Argumentaire : autorisation FDA de la notification d'hypertension de l'Apple Watch",
  '',
  `Position : **POUR** · exécution \`${prep.run_id}\` · modèle \`${prep.modele}\` · prompt \`redacteur_v1\``,
  '',
  `> ⚠ : paragraphe signalé par les garde-fous (G2 citations, G4 chiffres, G5 formulations absolues). Détail dans \`verif_${prep.run_id}.json\`.`,
  '',
];
for (const s of sections) {
  lignes.push(`## ${s.section.titre}`, '');
  if (s.g1.length) lignes.push(`> ⚠ G1 : ${s.g1.join(' ; ')}`, '');
  for (const p of s.paragraphes) lignes.push(`${p.alertes.length ? '⚠ ' : ''}${p.texte}${renvoi(p.citations, s.chunks)}`, '');
}
lignes.push('## Références', '');
for (const [doc, n] of numeros) {
  const d = prep.meta.find((x) => x.doc_id === doc);
  lignes.push(`${n}. ${d.reference} ${d.url}`);
}
const paragraphes = sections.flatMap((s) => s.paragraphes);
const resume = {
  paragraphes: paragraphes.length,
  signales: paragraphes.filter((p) => p.alertes.length).length,
  g1: sections.reduce((n, s) => n + s.g1.length, 0),
};
const verif = {
  run_id: prep.run_id, modele: prep.modele, resume,
  sections: sections.map((s) => ({
    id: s.section.id, g1: s.g1, alertes_section: s.alertes_section, selection: s.stats,
    paragraphes: s.paragraphes, contre_arguments_traites: s.contre_arguments_traites,
    chunks_recuperes: s.chunks.map(({ texte, ...c }) => c),
  })),
};
const run = {
  run_id: prep.run_id, horodatage: $now.toISO(), workflow: '10-argumentaire',
  modele: prep.modele, version_modele: sections.find((s) => s.version)?.version,
  prompts: ['redacteur_v1.md', 'sections.json v1'], sections: sections.map((s) => s.section.id),
  appels: { chat: sections.length, embeddings: sections.reduce((n, s) => n + s.stats.requetes, 0) },
  tokens: sections.map((s) => s.usage), duree_s: Math.round((Date.now() - prep.debut) / 1000), ...resume,
};
const fichier = (nom, contenu, mimeType, ajout = false) => ({
  json: { nom, ajout },
  binary: { data: { data: Buffer.from(contenu, 'utf8').toString('base64'), mimeType, fileName: nom } },
});
return [
  fichier(`argumentaire_${prep.run_id}.md`, lignes.join('\n') + '\n', 'text/markdown'),
  fichier(`verif_${prep.run_id}.json`, JSON.stringify(verif, null, 2) + '\n', 'application/json'),
  fichier('runs.jsonl', JSON.stringify(run) + '\n', 'application/x-ndjson', true),
];

// Lecture des entrées versionnées (prompts/sections.json, prompts/redacteur_v1.md, corpus/meta.json),
// puis un item par section demandée dans Paramètres, dans l'ordre de la consigne. La conclusion est traitée après la boucle.
const { modele, sections: demandees } = $('Paramètres').first().json;
const fichiers = {};
$input.all().forEach(({ json }, i) => {
  fichiers[$('Lire les fichiers').itemMatching(i).binary.data.fileName] = json.data;
});
const config = JSON.parse(fichiers['sections.json']);
const inconnues = demandees.filter((id) => !config.sections.some((s) => s.id === id));
if (inconnues.length) throw new Error(`Paramètres : section(s) inconnue(s) : ${inconnues.join(', ')}`);
const sections = config.sections.filter((s) => demandees.includes(s.id) && s.id !== 'conclusion');
if (!sections.length) throw new Error('Paramètres : il faut au moins une section en plus de la conclusion');
const commun = {
  run_id: $now.toFormat('yyyyLLdd-HHmmss'),
  debut: Date.now(),
  modele,
  parametres: config.parametres_retrieval,
  meta: JSON.parse(fichiers['meta.json']),
  template: fichiers['redacteur_v1.md'],
  conclusion: demandees.includes('conclusion') ? config.sections.find((s) => s.id === 'conclusion') : null,
};
return sections.map((section) => ({ json: { ...commun, section } }));

// Paramètres de l'exécution, à modifier ici.
// Quota de gemini-3.8-flash au plan gratuit : 5 appels par minute, 20 par jour (remise à zéro à minuit, heure du Pacifique).
// Une exécution complète (8 sections + conclusion) fait 9 appels de chat : pour déboguer, lister 1 ou 2 sections.
// Pas d'exécution complète sans l'accord du groupe (pipeline.md, section 1).
// Identifiants (prompts/sections.json) : contexte, enjeux_fda, technique, ethique, social_economique,
// reglementaire, parcours_soins, autres, conclusion (rédigée après les autres, à partir des sections générées).
return [{ json: {
  modele: 'gemini-3.8-flash',
  sections: ['ethique', 'reglementaire', 'conclusion'],
} }];

// Requêtes de la section en cours : 2 ou 3 angles + 1 requête « contre » (prompts/sections.json).
const { section } = $input.first().json;
return [
  ...section.requetes.map((requete) => ({ json: { section, requete, contre: false } })),
  { json: { section, requete: section.requete_contre, contre: true } },
];

// Conclusion (pipeline.md) : pas de nouvelle recherche. Ses extraits sont les chunks déjà cités par les sections
// (paragraphes et contre-arguments traités), et G2 vérifie qu'elle ne cite qu'eux. Les sections rédigées vont au rédacteur.
const sections = $input.all().map(({ json }) => json);
const chunks = new Map();
for (const s of sections) {
  const recuperes = new Map(s.chunks.map((c) => [c.chunk_id, c]));
  for (const id of [...s.paragraphes.flatMap((p) => p.citations), ...s.contre_arguments_traites]) {
    if (recuperes.has(id) && !chunks.has(id)) chunks.set(id, recuperes.get(id));
  }
}
const sections_redigees = sections
  .map((s) => [`### ${s.section.titre}`, ...s.paragraphes.map((p) => `${p.texte} (citations : ${p.citations.join(', ') || 'aucune'})`)].join('\n\n'))
  .join('\n\n');
return [{ json: {
  section: $('Préparer les sections').first().json.conclusion,
  chunks: [...chunks.values()],
  stats: { requetes: 0, candidats: chunks.size, retenus: chunks.size },
  sections_redigees,
} }];
